"use strict";
/* DANI · fx.js — جلا (همه قابل‌خاموش، db.set.fx {hap,anim}):
   (۱) لرزش ریز روی اقدام‌های مهم (navigator.vibrate) (۲) «پاپ» نرم روی دکمه‌ها (احترام به کاهش حرکت سیستم)
   (۳) صفحه‌ی «چه چیزی تازه است» (یک‌بار بعد از هر نسخه‌ی تازه + دکمه در برگه‌ی راهنما)
   (۴) نمونه‌داده برای آشنایی (فعالیت و ثبت‌های علامت‌دار smp؛ با یک دکمه پاک می‌شود) */
(function(){
const T=window.daniT;
const FX=()=>{const s=db.set;if(!s.fx||typeof s.fx!=='object')s.fx={};if(s.fx.hap===undefined)s.fx.hap=1;if(s.fx.anim===undefined)s.fx.anim=1;return s.fx};
const VER='2026.11.136';
/* ---------- لرزش و پاپ ---------- */
const HAP=/^(qk_go|nx_go|nx_sw|pf_add|tp_ap|bin_rs|ex_save|ab_now|ql_|pm_|tm_|tstart|tfinish|hab|ob_log|ob_go|dnd_set|ls_now|dk_)/;
const reduce=()=>{try{return matchMedia('(prefers-reduced-motion: reduce)').matches}catch(e){return false}};
document.addEventListener('click',e=>{const b=e.target.closest&&e.target.closest('button,[data-a]');if(!b)return;const a=b.dataset&&b.dataset.a||'';
  const f=FX();
  if(f.hap&&(b.classList.contains('p')||HAP.test(a))){try{navigator.vibrate&&navigator.vibrate(12)}catch(x){}}
  if(f.anim&&!reduce()&&(b.classList.contains('p')||b.classList.contains('chip')||HAP.test(a))){b.classList.remove('fxpop');void b.offsetWidth;b.classList.add('fxpop');setTimeout(()=>b.classList.remove('fxpop'),320)}},true);
const st=document.createElement('style');
st.textContent='@keyframes fxpop{0%{transform:scale(1)}40%{transform:scale(.92)}100%{transform:scale(1)}}.fxpop{animation:fxpop .3s ease}@media(prefers-reduced-motion:reduce){.fxpop{animation:none}}';
document.head.appendChild(st);
/* ---------- چه چیزی تازه است ---------- */
const WN=[
 ['🃏','مرور فلش‌کارت هوشمندتر شد: کارتی که «دوباره» یا «سخت» بزنی بعد از چند کارت دیگر برمی‌گردد (نه پشت سر هم)، چند قدم یادگیری دارد و کارت قدیمیِ فراموش‌شده به ۱ روز برنمی‌گردد. کارت چهار بار فراموش‌شده «سخت‌گیر» علامت می‌خورد و تعداد کارت‌های «مسلط» دیده می‌شود. جدید: «جلسه‌ی مطالعه» در صفحه‌ی دوره، با بخش‌های تیک‌دار (مرور خطاها، یادگیری، فلش‌کارت، تمرین، آزمونک، جمع‌بندی).','Smarter flashcard review: a card you answer Again or Hard comes back after a few other cards (not right behind), has learning steps, and a forgotten old card no longer resets to 1 day. Cards forgotten four times are flagged as leeches and mastered cards are counted. New: study Sessions on the course page with tick-able parts (review mistakes, learn, flashcards, practice, quiz, wrap-up).'],
 ['📚','«ورود و مدیریت» دوره‌ها منظم‌تر شد: هر دوره حالا چند «فایل» دارد (فصل ۱، فصل ۲، …) و جمع‌شده زیر همان دوره نمایش داده می‌شود. فایل ادامه‌دار خودکار زیر همان دوره می‌رود؛ هر فایل را می‌شود تغییر نام داد، با نسخه‌ی کامل‌تر جایگزین کرد (با پیش‌نمایش؛ پیشرفت می‌ماند) یا فقط همان فایل را حذف کرد. دوره‌های قبلی چیزی از دست نمی‌دهند.','Course Import & Manage is tidier: each course now has several files (Chapter 1, 2, …) collapsed under it. A continuation file goes under its course automatically; rename a file, replace it with a fuller version (with a preview; progress is kept) or delete just that file. Existing courses lose nothing.'],
 ['☰','«Menu / منو» کامل‌تر شد: «اندازه» حالا خود نوار منو را کوچک/بزرگ می‌کند (نه فقط متن)؛ برای منوی پایین/بالا/شناور «فاصله از لبه‌ی صفحه» داری؛ نمایش آیتم‌ها: فقط آیکون / فارسی + English / فقط فارسی / فقط English؛ سربرگ (نام، شعار، هیچ)، اندازه‌ی آیکون، شفافیت نوار، گوشه‌ی گرد یا تیز و سایه. همه جدا برای هر تم و اختیاری؛ چیزی حذف نشد.','Menu card extended: Size now scales the whole bar (not just text); bottom/top/floating menus get distance from the screen edge; item display: icons only / Persian + English / Persian only / English only; header (name, tagline, none), icon size, bar opacity, round or sharp corners and shadow. All per theme and optional; nothing removed.'],
 ['🔁','مرور تازه شد: کارتِ هر مبحث فقط بعد از باز/مطالعه‌کردن همان درس در مرور می‌آید. بالای مرور می‌توانی محدوده را انتخاب کنی: همه‌ی بازشده‌ها، یک دوره، یک مبحث (حتی کارت‌های موعدنرسیده)، یا «بسته‌ی پیشنهادی سازنده». آخر هر درس بخش «خودت را بسنج» هست. سازنده‌ی پک می‌تواند گروه مرور بسازد.','Review reworked: a topic\'s cards only enter review after you open/study that lesson. Pick the scope on top: all opened, a course, a topic (even cards not yet due) or a builder-suggested pack. Every lesson ends with «Test yourself». Pack builders can define review groups.'],
 ['🧰','آیتم تازه‌ی منو «Tools / ابزارها» (بعد از «برنامه»): مسیر روشن (از صفحه‌ی خانه به اینجا آمد؛ روی خانه فقط یک چیپ کوچک مانده که پنهان‌شدنی است)، ماتریس آیزنهاور (چهار خانه، افزودن از موعدها، فرستادن به برنامه‌ی امروز) و قانون ۲ دقیقه (تایمر؛ کار بزرگ‌تر به آیزنهاور می‌رود). با «Menu / منو» می‌توانی این آیتم را پنهان کنی.','New menu item «Tools» (after Plan): Clear Path (moved off Home, a small hideable chip stays), Eisenhower matrix (four boxes, add from deadlines, send to today\'s plan) and the 2-minute rule (timer; longer tasks go to Eisenhower). You can hide the item from the Menu card.'],
 ['🧮','پک آموزشی: (۱) در متغیرها و پاسخ عددی حالا ln، log، sin، cos، tan، exp، pow، pi، e و √ هم کار می‌کند؛ (۲) جواب هم‌ارز پذیرفته می‌شود (۲/√۳ همان ۱٫۱۵۴۷ است)؛ (۳) برچسب «تله» روی سؤال و گزینه: بعد از اشتباه دیده می‌شود و در دفترچه‌ی خطا شمرده می‌شود؛ (۴) کارت لغت: اجزا، مترادف، متضاد، خانواده، هم‌نشین، یادیار؛ (۵) سقف فلش‌کارت ۶۰۰۰ شد؛ (۶) درس و سؤال می‌توانند دکمه‌ی ویدیو با زمان شروع داشته باشند.','Course packs: (1) ln, log, sin, cos, tan, exp, pow, pi, e and √ work in variables and numeric answers; (2) equivalent answers are accepted (2/√3 equals 1.1547); (3) a «trap» tag on questions and choices shows after a mistake and is counted in the error notebook; (4) word cards: parts, synonyms, antonyms, family, collocations, memory aid; (5) flashcard cap is now 6000; (6) lessons and questions can have a video button with a start time.'],
 ['☰','کارت «Menu / منو» در «ظاهر و تم ← سفارشی»: اندازه‌ی منو (٧٠ تا ١۴٠٪ مثل دکمه‌ی راهنما)، برچسب زیر آیتم (فارسی + English / فقط یکی / بدون برچسب)، متن ضخیم، پنهان‌کردن سربرگ و پنهان/نمایان‌کردن آیتم‌ها. همه‌چیز جدا برای هر تم است و آیتم تازه‌ی منو خودکار نمایان می‌شود. «خانه» و «تنظیمات» همیشه می‌مانند.','New «Menu» card in Theme ← Customize: menu size (70–140%, like the help button), label under item (both / one language / none), bold text, hide header and hide/show items. Everything is per theme and new menu items appear automatically; Home and Settings always stay.'],
 ['📦','«خروجی کامل تم» (ظاهر و تم ← بسته‌های تم): یک فایل dani-themepack با رنگ و چیدمان، آیکون‌ها، تصویرها، جمله‌ها و CSS (و کد، برای تمی که بسته‌ی واردشده است). با «وارد کردن» دوباره برمی‌گردد. کد تم‌های داخلی در خود برنامه است و در فایل نمی‌آید.','«Full theme export» (Theme ← Theme packs): one dani-themepack file with colours and layout, icons, images, quotes and CSS (and code, for a theme that is an imported pack). Re-import it any time. Built-in themes\' code lives inside the app and is not in the file.'],
 ['🎨','استودیوی تم برگشت: «ساخت از تم فعلی»، ویرایش و کپی تم‌های خودت دوباره در «ظاهر و تم ← سفارشی» است (در یک نسخه‌ی قبل به‌اشتباه از صفحه افتاده بود).','Theme Studio is back: “Create from current theme”, edit and copy your own themes are in Look & themes → Customize again (it was accidentally dropped from the page in an earlier version).'],
 ['🧩','ادغام درس‌ها حالا فقط در «آکادمی ← ورود و مدیریت» است (از صفحه‌ی یادگیری برداشته شد). همه‌ی ادغام‌های قبلی را با تاریخ می‌بینی، هر کدام را جدا برمی‌گردانی (به ترتیب)، نامش را عوض می‌کنی یا درس دیگری به آن اضافه می‌کنی. تا ۸ ادغام اخیر نگه‌داری می‌شود.','Merging subjects now lives only in Academy → Import & manage (removed from Learning). See every past merge with its date, undo any of them (in order), rename it or add another subject to it. The last 8 merges are kept.'],
 ['🎛','استودیوی نماد درست شد: تعویض تک‌تک آیکون‌ها و اندازه‌ی آیکون حالا مال هر تم است و بین تم‌ها نمی‌پرد؛ فهرست آیکون‌های قابل تعویض از منوی برنامه ساخته می‌شود (آیتم تازه خودکار می‌آید)؛ آیکون‌های ایموجی هم با اندازه بزرگ/کوچک می‌شوند؛ اگر آیکون دستی روی ست نماد نشسته باشد اعلام می‌شود و می‌توانی پاکش کنی.','Icon Studio fixed: per-icon swaps and icon size now belong to each theme and no longer leak between themes; the swappable list is built from the app menu (new items appear automatically); emoji icons scale with the size setting; a note shows when hand-picked icons override a set, with a clear button.'],
 ['🧠','سؤال‌های آموزشی هوشمندتر شدند: یک متن مشترک برای چند سؤال (در حالت تمرکز بالای صفحه ثابت می‌ماند)، کلوز با چند جای خالی، جای‌گذاری جمله در [۱] تا [۴]، سؤال کفایت داده، راهنمای مرحله‌ای (💡) در تمرین، زمان پیشنهادی هر سؤال، متادیتای آزمون (مدت، سال، نمره‌ی منفی)، درس‌های «به‌زودی» و سؤال‌های متغیر که هر بار عددشان عوض می‌شود.','Smarter questions: one shared passage for several questions (pinned at the top in focus mode), multi-blank cloze, sentence placement [1]–[4], data sufficiency, step-by-step hints (💡) in practice, suggested time per question, exam metadata (duration, year, penalty), "coming soon" lessons and variable questions whose numbers change each time.'],
 ['🎯','تمرکز در آکادمی: وقتی داخل درس، آزمون یا مرور فلش‌کارت هستی همهٔ شلوغی‌ها (Good morning، زبانه‌ها، منو) کنار می‌رود و فقط یک نوار باریک می‌ماند: ← برگشت، عنوان و پیشرفت، و ⋮ (نمایش منو، خروج از تمرکز، خاموش کردن). صورت سؤال را با 📌 بالای صفحه سنجاق کن تا موقع اسکرول ثابت بماند.','Academy focus: inside a lesson, exam or flashcard review everything else (Good morning, tabs, menu) is hidden and only a slim bar stays: ← Back, title/progress and ⋮ (show menu, leave focus, turn off). Pin the question stem with 📌 so it stays while you scroll.'],
 ['🧩','نمادها یکدست‌تر شدند: هر نمادی که تم برایش نماد اختصاصی ندارد حالا داخل قاب هم‌رنگ تم می‌آید و ریتم تم به‌هم نمی‌خورد. ست‌های نمادِ یکسان فقط یک‌بار نشان داده می‌شوند («استفاده در N تم»). هر آیتم تازهٔ منو خودکار در همهٔ تم‌ها وارد می‌شود. نمادهای اختصاصی کامل‌تر بعداً می‌آید.','Icons are now consistent: any icon a theme has no custom art for sits in a theme-coloured frame so the rhythm holds. Identical icon sets show once (“used in N themes”). Any new menu item joins all themes automatically. Fully custom icons come later.'],
 ['🛠','دو باگ رفع شد: (۱) در تنظیمات، با زدن روی یک گزینه (مثلاً انتخاب آهنگ) بخش/کارت دیگر جمع نمی‌شود و حالت باز/بسته‌ای که خودت گذاشتی می‌ماند. (۲) تم‌های روشن بدون پالت (کلاسیک، هیبرید) وقتی حالت برنامه تیره/خودکار است تیره می‌شدند و دکمه‌ی «روشن» برای آن‌ها اثر نداشت؛ حالا اثر دارد و برچسب «پیش‌فرض تم» درست است.','Two bugs fixed: (1) in Settings, tapping an option (e.g. picking a ringtone) no longer collapses the section — the open/closed state you chose is kept. (2) Light themes without their own palette (Classic, Hybrid) turned dark when the app mode was dark/auto and the “Light” button did nothing; it now works and the “theme default” label is accurate.'],
 ['🃏','مرور فلش‌کارت مثل انکی شد: شمارنده‌ی جدید/یادگیری/مرور، فاصله‌ی بعدی روی هر دکمه (دقیقه، روز، ماه)، «دوباره» همان روز برمی‌گردد، برگشت (↩)، پرچم و منوی ⋮. کارت لغت: اول فقط لغت و صدا، بعد IPA، معنی انگلیسی، فارسی، مثال. هیچ قابلیتی حذف نشد.','Flashcard review is now Anki-style: New/Learning/Review counters, next interval on every button, “Again” returns the same day, undo (↩), flag and a ⋮ menu. Word cards: word + audio first, then IPA, English meaning, Persian, examples. Nothing removed.'],
 ['🛍','ظاهر و تم ساده شد: فقط سه زبانه «فروشگاه | سفارشی | بسته‌های تم». در فروشگاه تم‌ها (با پوشه‌ها، پوشهٔ ایتاچی هم دوباره باز می‌شود) و نمادها هست. زدن روی هر تم پیش‌نمایش باز می‌کند: حالت، رنگ، شکل منو، گوشه‌ها و نمادها، و پیش‌فرض هر چیز مال خودِ همان تم است و روی تم بعدی نمی‌ماند.','Look & themes simplified: just three tabs — Store | Customize | Theme packs. The store has themes (with folders; the Itachi folder opens again) and icons. Tapping a theme opens a preview: mode, colour, menu, corners and icons; every default belongs to that theme and does not carry over to the next one.'],
 ['🔣','نمادها: مجموعه‌های آیکونِ واقعیِ تم‌ها (مثل Eren، Itachi) روی هر تمی قابل استفاده‌اند؛ استودیوی آیکون زیرش است. «بسته‌های کامل»، «قالب‌ها»، «تم‌های من»، «استودیو تم»، «شکل منو» و «Look & Feel» حذف شدند؛ کارت‌های داشبورد و حس برنامه به «منو و صفحهٔ خانه» رفتند. در سابقهٔ بسته‌ها می‌توانی نام تم و متن سربرگ را عوض کنی.','Icons: real theme icon sets (Eren, Itachi…) usable on any theme, with Icon Studio below. Removed: Full bundles, Templates, My themes, Theme Studio, Menu style and Look & Feel; Dashboard cards and App feel moved to “Menu & home”. In the pack history you can rename a theme and its header text.'],
 ['🧹','آکادمی: حالا می‌توانی مبحث، فصل و تک‌تک سؤال‌ها را حذف کنی و سؤال را به مبحث دیگر ببری (با به‌روزرسانی zip برنمی‌گردند). پاسخ عددی به شکل کسر مثل ۷/۶ هم درست تصحیح می‌شود.','Academy: you can now delete single topics, chapters and questions and move a question to another topic (they stay deleted after zip updates). Numeric answers like 7/6 are graded correctly.'],
 ['🧭','هر دوره می‌تواند دسته‌هایش را «جلسه»، «بخش» یا «هفته» بنامد، و «مسیرهای مطالعه» دارد: فهرست مرتبی از مبحث‌ها (مثل جلسه ۱ تا ۳) بدون شلوغی. نوع درس (زبان، ریاضی، جیمت) شکل فلش‌کارت را عوض می‌کند و در دفترچه فرمول «ساخت کارت» هست.','Each course can call its groups “session”, “section” or “week”, and has Study paths — ordered lists of topics. The subject type (language, math, GMAT) shapes flashcards, and the formula notebook has “Make card”.'],
 ['🛡','ایمنی: تصویر SVG ناامن رد می‌شود، zip بمب قبل از پرشدن حافظه متوقف می‌شود، «$5 و $6» در متن فرمول حساب نمی‌شود، و زمان آزمون بعد از بسته‌شدن ناگهانی برنامه درست برمی‌گردد.','Safety: unsafe SVG images are rejected, zip bombs stop before filling memory, “$5 and $6” is no longer treated as a formula, and exam time is restored correctly after an abrupt close.'],
 ['🎁','فروشگاه: «بسته‌های کامل» — ۱۴ بسته که قالب، آیکون‌ها و شکل منو را با هم عوض می‌کنند (مثلاً «نیمه‌شبِ نئونی»). پیش‌نمایش دارد و با «↩ برگشت» همه‌چیز به قبل برمی‌گردد.','Store: “Full bundles” — 14 bundles that set theme, icons and menu style together, with preview and one-tap undo.'],
 ['🔣','فروشگاه حالا بخش «نمادها (آیکون‌ها)» دارد: ۱۳ بستهٔ آیکون با پیش‌نمایش (خطی، پررنگ، دایره‌ای، کاشی رنگارنگ، شش‌ضلعی، ایموجی…) و سه مدل تازه: براق، نئون و خمیری سه‌بعدی. یک‌ضربه طرح، قاب و رنگ را با هم عوض می‌کند.','The store now has “Icon packs”: 13 packs with previews and three new looks (Glossy, Neon, Clay 3D). One tap sets icon set, frame and colour together.'],
 ['☰','منوی کشویی حالا با زدن هر جای بیرون از منو یا دکمهٔ برگشت گوشی بسته می‌شود؛ لازم نیست حتماً گزینه‌ای را انتخاب کنی.','The slide-out menu now closes when you tap outside it or press the phone’s Back button; no need to pick an item.'],
 ['🛍','تنظیمات تم حالا چهار بخش دارد: «فروشگاه» (قالب‌ها با پیش‌نمایش و انتخاب شکل منو؛ یک‌ضربه همه‌چیز عوض می‌شود)، «سفارشی» (شکل منو: پایین، شناور، بالا، کناری، فقط آیکون + رنگ و آیکون‌ها)، «تم‌های من» (فهرست فشرده) و «استودیو». بخش «پس‌زمینه» برداشته شد.','Theme settings now has four tabs: Store (templates with preview and menu style), Customize (menu style: bottom, floating, top, side, icons-only + colours & icons), My themes, Studio. The “Background” section was removed.'],
 ['✎','مداد تغییر نام درس و فصل درست شد. دکمه‌های ❓ دیگر روی متن و منو نمی‌افتند: «سؤال از این درس» یک دکمهٔ کوچک بالای درس است و برای پرسیدن از یک بخش، روی همان بخش بزن تا دکمهٔ کوچکش بیاید.','Rename pencil fixed. ❓ buttons no longer overlap text or the menu: a small “Ask about this lesson” chip at the top; tap a section to reveal its small ask button.'],
 ['🔊','فلش‌کارت قوی‌تر: 🔊 تلفظ انگلیسی با صدای خود گوشی (و 🐢 آهسته)، «حالت املا» (بشنو و بنویس)، کارت جای‌خالی با {{ }}، مثال/تلفظ زیر پاسخ، و سقف کارت جدید در روز.','Stronger flashcards: 🔊 English pronunciation using your phone\'s voice (🐢 slow), spelling mode, cloze cards with {{ }}, example/pronunciation line, and a daily new-card cap.'],
 ['🧩','آزمون‌ساز چنددرسی: در «مرکز آزمون» دکمهٔ «آزمون‌ساز» را بزن؛ از درخت مجموعه ← درس ← فصل ← مبحث هرچه خواستی تیک بزن، ترتیبش را با ↑↓ بچین (یا تصادفی)، و چند درس را در یک آزمون (حتی شبیه‌ساز کنکور) ترکیب کن. نتیجه به آمار هر درس برمی‌گردد.','Multi-subject exam builder: in Exam Center tap “Builder”, tick subjects/chapters/topics from the tree, order them (or shuffle), mix several subjects into one exam (even a konkur simulator). Results feed each subject\'s stats.'],
 ['✎','فصل‌ها جدا و بازشونده (فصل ۱، فصل ۲…)؛ با ✎ نام درس، فصل و مبحث را عوض کن (با به‌روزرسانی دوره پاک نمی‌شود). داخل هر مبحث «🛠 ساخت» برای فلش‌کارت و سؤال خودت. «درس‌های قدیمی» با یک دکمه به درس‌ها منتقل می‌شود.','Chapters are separate and collapsible; ✎ renames subjects, chapters and topics (kept across updates); 🛠 build cards/questions inside a topic; old lessons move into subjects with one button.'],
 ['🧩','ادغام درس‌های هم‌موضوع: ریاضی (حد + مشتق + آزمون مخلوط) و انگلیسی (دو دوره‌ی گرامر) هر کدام یک درس با چند فصل می‌شوند. شناسه‌ها، پیشرفت، خطاها و آزمون‌ها می‌مانند؛ سؤال‌های آزمون مخلوط برچسب «آزمون» می‌گیرند؛ دکمه‌ی برگرداندن ادغام هست.','Merge related subjects into one with chapters; progress, mistakes and attempts kept; undo available.'],
 ['🎓','آکادمی یکپارچه: «درس‌ها» و «دوره‌ها» یکی شد. داخل هر درس زبانه‌های فصل‌ها، فرمول‌ها، کارت‌ها، خطاها، نشانک‌ها و آزمون هست؛ دفترچه فرمول با ارجاع به تدریس، سؤال و صفحه‌ی جزوه؛ مسیر مجموعه ‹ درس ‹ فصل ‹ مبحث بالای هر مبحث؛ «ورود و مدیریت» جدا از منابع؛ منابع یکی و جمع‌وجور؛ پرسیدن مجموعه هنگام نصب.','Unified Academy: Lessons+Courses merged; per-subject tabs (chapters, formulas, cards, mistakes, bookmarks, exam); formula notebook; breadcrumb; import/manage separate; one compact Resources page; collection chosen on install.'],
 ['📚','آکادمی مبحث‌محور: «مجموعه» (مثل MBA) ← درس ← فصل ← مبحث. درصد تسلط روی هر فصل و مبحث، فلش‌کارت مخصوص هر مبحث، پیشنهاد گروه‌بندی خودکار و هشدار محتوای تکراری. چیزی پاک نشد.','Topic-centred Academy: collections → subjects → chapters → topics, mastery %, per-topic flashcards, auto-grouping and duplicate warning. Nothing deleted.'],
 ['🎨','«ظاهر و تم» مرتب شد: پنج زبانه (تم · رنگ و حالت · آیکون‌ها · پس‌زمینه · حس و کارت‌ها)؛ حالت «خودکار (طبق گوشی)» اضافه شد و برای کاربر تازه پیش‌فرض است. چیزی حذف نشد.','“Look & themes” is tidier: five tabs (Theme · Colour & mode · Icons · Background · Feel & cards); an “Auto (follow phone)” mode is new and the default for new users. Nothing was removed.'],
 ['🎓','آکادمی مرتب شد: چهار بخش (یادگیری · مرور · آزمون · منابع) با زیرزبانه‌ها؛ همه‌ی صفحه‌ها و داده‌های قبلی هستند، فقط تکراری‌ها و کارت‌های خالیِ «به‌زودی» برداشته شد.','Academy tidied: four sections (Learn · Review · Exams · Resources) with sub-tabs; every earlier page and your data are kept — only duplicates and the empty “coming soon” cards went.'],
 ['🎯','آکادمی: «مرکز آزمون» — چند مبحث/فصل/درس را با هم انتخاب کن، فقط خوانده‌شده‌ها یا ضعیف‌ها، آزمون‌های سال‌های گذشته و شبیه‌ساز کنکور با نمره‌ی منفی. 🔥 زنجیره فقط با کارِ مفید برای هدف ساخته می‌شود و اعلان «فرصت آخر» دارد.','Academy: “Exam Center” — mix several topics/chapters/lessons, studied-only or weak topics, past exams and a konkur-style simulator with negative marking. 🔥 Streaks now need goal-useful work and have a “last chance” alert.'],
 ['🧭','«مسیر روشن» حالا «برگشت به مسیر» دارد: گم‌شده/اهمال/بی‌حوصله/چند روز دور؛ مانع‌یابی، راه‌حل و اطلاعات، برنامه‌ی بازگشت نرم و پیگیری «چه شد؟».','Clear Path now has “Back on track”: lost / procrastinating / no drive / away; obstacles, solutions & info, a soft comeback plan and a “how did it go?” follow-up.'],
 ['🎓','«پروژه‌ها» خیلی جمع‌وجور شد: سوییچ «پروژه‌ها | موعدها»، هر پروژه یک ردیف با چهار زبانه (وضعیت، بخش‌ها، عادت و یادآوری، ویرایش) و موعدها در سه گروه؛ هیچ قابلیتی کم نشد.','Projects is much tidier: a “Projects | Deadlines” switch, each project is one row with four tabs, and deadlines in three groups; nothing was removed.'],
 ['🧭','ابزار تازه‌ی اختیاری «مسیر روشن / Clear Path»: نگرانی را در چهار قدم به یک اقدام کوچک تبدیل کن و به برنامه‌ی امروز بفرست. در «شخصی‌سازی امروز» روشنش کن.','New optional tool “Clear Path”: turn a worry into one small action in four steps and send it to today\'s plan. Turn it on in “Customize Today”.'],
 ['🧩','کپی‌شدن کارت «ثبت فعالیت» (وقتی پومودورو یا ثبت سریع را می‌زدی) درست شد: فقط یک کارت می‌ماند.','Fixed the duplicated “Activity Log” card (when tapping Pomodoro or Quick log): only one card remains.'],
 ['📌','دیگر صفحه با زدن دکمه‌ها (پومودورو، ثبت سریع و …) به بالا نمی‌پرد و کارت‌های جمع‌شونده‌ای که باز کرده‌ای بسته نمی‌شوند.','The page no longer jumps to the top when you tap buttons (Pomodoro, Quick log…), and collapsible cards you opened stay open.'],
 ['🎓','«پروژه‌ها» جمع‌وجورتر شد: توضیح بالا پشت ⓘ، دکمه‌ها در دو ردیف، کارت‌های خالی باریک و کارت «موعدها» تک‌خطی؛ هیچ قابلیتی کم نشد.','Projects is tidier: top hint behind ⓘ, buttons in two rows, slim empty cards and a one-line Deadlines card; nothing was removed.'],
 ['📅','برنامه: زبانه‌های «ساعت پر» و «تقویم» هم جمع‌وجور شدند — توضیح‌ها پشت ⓘ، روزهای هفته در یک ردیف، خانه‌های تقویم کوتاه‌تر؛ هیچ قابلیتی کم نشد.','Plan: “Busy” and “Calendar” tabs are tidier — hints behind ⓘ, weekdays in one row, shorter calendar cells; nothing was removed.'],
 ['🗓','صفحه‌ی برنامه جمع‌وجورتر شد: راهنماها پشت دکمه‌ی ⓘ، ردیف «اخیراً» قابل‌کشیدن، دکمه‌های ساعت‌ها در یک ردیف و کارت‌های بسته باریک‌تر؛ هیچ قابلیتی کم نشد.','Plan page is tidier: hints behind an ⓘ button, a swipeable “Recent” row, time buttons in one row and slimmer closed cards; nothing was removed.'],
 ['🧭','صفحه‌ی برنامه: نوار تب‌ها (برنامه‌ی روز، توقع، ساعت پر…) حالا همیشه تب فعال را وسط و قابل‌دیدن نگه می‌دارد؛ قبلاً در بعضی تب‌ها از صفحه بیرون می‌رفت.','Plan page: the tab strip now keeps the active tab centred and visible; before, on some tabs it scrolled off-screen.'],
 ['🍎','آماده‌تر برای آیفون: بعد از «افزودن به صفحه‌ی اصلی» در Safari، برنامه تمام‌صفحه و با اسم DANI باز می‌شود.','Better on iPhone: after "Add to Home Screen" in Safari the app opens full-screen with the name DANI.'],
 ['🗂','صفحه‌ی امروز: «تایم‌لاین»، «فهرست ثبت‌ها» و «نتیجه‌ی امروز» حالا یک کارت با سه تب‌اند؛ عدد «ثبت‌شده» همیشه بالای کارت است و هیچ دکمه‌ای کم نشد. خاموش‌کردن: شخصی‌سازی صفحه‌ی امروز ← «کارت تب‌دار».','Today page: "Timeline", "Entries" and "Result" are now one card with three tabs; the logged-time number always stays on top and no button was removed. Turn off: Customize Today → "Tabbed card".'],
 ['📖','«شخصی‌سازی صفحه‌ی امروز»: گزینه‌ی «درس بعدی (آکادمی)» حالا در تم‌هایی که خانه‌ی اختصاصی ندارند هم کارت درس بعدی را نشان می‌دهد (قبلاً تیک می‌خورد ولی چیزی نمی‌آمد).','"Customize Today": the "Next lesson (Academy)" option now shows the next-lesson card also in themes without their own home (it used to be ticked but showed nothing).'],
 ['🧹','خانه: کارت «موعد بعدی» وقتی موعدی نیست یک ردیف کوچک می‌شود (وقتی موعد داری همان کارت کامل با هشدارها و ظاهرها). «درس بعدی (آکادمی)» وقتی درسی نیست پیام نشان می‌دهد. پنجره‌ی شخصی‌سازی دیگر زیر نوار به‌روزرسانی و دکمه‌ی راهنما نمی‌رود.','Home: the "Next deadline" card collapses to one slim row when you have no deadline (with deadlines you still get the full card, alerts and styles). "Next lesson (Academy)" shows a message when there is no lesson. The customize window is no longer covered by the update bar and help button.'],
 ['🎯','کارت «بعدی چی؟» دیگر خودش در خانه نیست (بعد از ادغام تکراری بود). هنوز در برگه‌ی «بعدی چی؟»ی نوار پایین و با «شخصی‌سازی خانه» قابل‌روشن‌کردن است.','The "What next?" card is no longer on Home by default (it duplicated the merged cards). It is still in the bottom toolbar sheet and can be turned on from Customize home.'],
 ['✨','ظاهر مدرن (مرحله‌ی ۱): کارت‌ها، عنوان‌ها، دکمه‌ها و ورودی‌ها نرم‌تر و گردتر شدند، با فاصله‌ی بهتر. فقط برای تم‌های ساده‌ی داخلی؛ تم‌های شخصیت‌دار ظاهر خودشان را نگه می‌دارند. کلید: تنظیمات ← ظاهر و تم.','Modern look (step 1): cards, titles, buttons and inputs are softer and rounder with better spacing. Only for the plain built-in themes; character themes keep their own look. Switch: Settings → Look & themes.'],
 ['🛠','پایداری اولین اجرا بعد از نصب: اگر فایلی دیر یا ناقص بارگذاری شود برنامه خودش یک‌بار کش را پاک و دوباره باز می‌شود؛ ورودی تاریخ و کارت موعد دیگر با این حالت خطا نمی‌دهند؛ دکمه‌ی «اجازه‌ی اعلان» در اولین اجرا صبر می‌کند تا اعلان آماده شود.','First-run stability after install: if a file loads late or incomplete the app clears its cache and reloads once; the date field and deadline card no longer error in that state; the "Allow notifications" button now waits for the notifier to be ready.'],
 ['🗺','«چرخه‌ی امروز» حالا نقشه‌ی زنجیره‌ات را نشان می‌دهد (۱۴ روز اخیر + فاصله تا نشان بعدی) و هر قدمِ راهنمای شروع یک تصویر کوچک دارد.','"Today\'s rhythm" now shows your streak map (last 14 days + distance to the next badge) and each Start-guide step has a small illustration.'],
 ['💬','بسته‌ی تم حالا می‌تواند جمله‌های شخصیت خودش را هم داشته باشد (فیلد quotes)؛ قاب جمله و جمله‌های خانه بدون بسته‌ی جدا کار می‌کنند.','A theme pack can now carry its own character quotes (the quotes field); the quote frame and home lines work without a separate pack.'],
 ['🧹','صفحه‌ی برنامه جمع‌وجورتر شد: سربرگ‌ها و زیرسربرگ‌های «ساعت پر · عادت · یادآور» یک ردیف قابل‌کشیدن‌اند، توضیح هر بخش پشت «ℹ️ این بخش چیست؟» است و خانه‌ی «آهنگ ساعت/هفته» در پروژه‌ها دیگر خالی و گنگ نیست.','Plan page tidied: tabs and sub-tabs are one swipeable row, each section\'s explainer is behind "ℹ️ What is this?", and the empty "pace h/week" box in Projects now shows a hint.'],
 ['🎓','ثبت خودکار زمان مطالعه‌ی آکادمی (اختیاری): بالای تب «دوره‌ها» روشنش کن و یک فعالیت انتخاب کن؛ وقتی در حال استفاده‌ای زمان جمع می‌شود و هنگام خروج در لاگ ثبت می‌شود.','Auto-log Academy study time (optional): turn it on above the Courses tab and pick an activity; time adds up while you use it and is logged when you leave.'],
 ['⏳','خط «واقع‌بینی» برنامه حالا از ۱۴ روز گذشته یاد می‌گیرد: اگر معمولاً بیشتر از برآوردت طول می‌کشد، برآورد واقعی را هم نشان می‌دهد.','The Plan "realism" line now learns from your last 14 days: if you usually take longer than planned it shows a realistic estimate.'],
 ['🧮','در صفحه‌ی برنامه یک خط «واقع‌بینی» اضافه شد: کل برنامه‌ی روز را با وقت آزادت (بیداری منهای ساعت‌های پر) مقایسه می‌کند و اگر جا نمی‌شود می‌گوید چقدر بیشتر است.','A new "realism" line on the Plan page compares the day\'s plan with your free time (waking hours minus busy blocks) and says how much it overshoots.'],
 ['🔔','اعلان سنجاق‌شده مدرن‌تر شد: دکمه‌های گرد و بزرگ جایشان را به کاشی‌های کوچکِ گوشه‌گرد دادند و نوشته‌ها جمع‌تر شدند (با ساخت APK جدید دیده می‌شود).','Pinned notification refreshed: big round buttons became compact rounded tiles with tighter text (visible after rebuilding the APK).'],
 ['⏱','تایمر یکپارچه شد: وقتی تایمر یا پومودورو فعال است یک نوار کوچک روی همه‌ی صفحه‌ها می‌ماند (مکث/ادامه با یک لمس). با لمس آن «صفحه‌ی تمرکز» تمام‌صفحه باز می‌شود، با دو ظاهر (حلقه‌ای یا آرام) و پس‌زمینه‌ی عکس تم، عکس خودت یا ساده، با تیرگی قابل تنظیم. حالت تمرکز قدیمی همین صفحه شد؛ چیزی حذف نشد.','Unified timer: a small bar stays on every page while a timer or Pomodoro runs (pause/resume in one tap). Tap it for a full-screen Focus page with two looks (ring or calm) and a theme-image, own-photo or plain background with adjustable dim. The old focus mode is now this page; nothing was removed.'],
 ['⚡','تنظیمات سریع‌تر شد (فهرست دیگر کل تب را نمی‌سازد) و دکمه‌ی گیج‌کننده‌ی «نمای قدیمی» برداشته شد؛ هر ورود به تنظیمات همین فهرست و صفحه‌های جداست. رندر صفحه‌ها هم سبک‌تر شد.','Settings is faster (the list no longer builds a whole tab) and the confusing “classic view” button is gone; every way into Settings now uses the list and its pages. Page rendering is lighter too.'],
 ['🧩','صفحه‌ی پروژه‌ها مرتب شد: بخش بزرگ «موعدها» حالا چند بخش جمع‌شونده‌ی برچسب‌دار است (فهرست، افزودن، پیش‌بینی، بدون پروژه، هشدارها، دسته‌ها، تنظیمات) و بالای صفحه دکمه‌های پرش دارد. چیزی حذف نشده. باز و بسته بودن بخش‌ها و جای اسکرول هم یادش می‌ماند.','Projects page tidied: the big “Deadlines” block is now labelled collapsible sections (list, add, forecast, no-project, alerts, categories, settings) with jump buttons on top. Nothing removed. Open sections and scroll position are remembered.'],
 ['🧭','تنظیمات حالا یک فهرست مرتب است (زبان، ظاهر، جمله‌ها، منو، اعلان‌ها، ویجت، پشتیبان، امنیت…). هر ردیف یک صفحه‌ی جدا با دکمه‌ی برگشت باز می‌کند. هیچ قابلیتی حذف نشده؛ «نمای تب‌ها» هم پایین فهرست مانده.','Settings is now a tidy list (language, look, sentences, menu, notifications, widget, backup, security…). Each row opens its own page with a back button. Nothing was removed; the classic tabs view stays at the bottom of the list.'],
 ['🆕','پیام «نسخه‌ی تازه آماده است» حالا یک نوار ماندگار با دکمه‌ی «به‌روزرسانی» است (دیگر یک ثانیه‌ای نمی‌رود). دکمه اول همه‌ی فایل‌های تازه را می‌گیرد، بعد برنامه را دوباره باز می‌کند.','The “new version ready” message is now a persistent bar with an “Update” button (no more one-second flash). It downloads everything new first, then restarts the app.'],
 ['🔄','دکمه‌ی کوچک «به‌روزرسانی اجباری» در راهنما (دکمه‌ی ✦) و صفحه‌ی update.html: اگر تغییرات تازه نمی‌نشست، حافظه‌ی نسخه‌ی قبلی پاک می‌شود و برنامه تازه بالا می‌آید. اطلاعات تو دست‌نخورده می‌ماند.','A small “Force update” button in Help (✦) and the update.html page: if new changes do not show up, the old-version cache is cleared and the app starts fresh. Your data is untouched.'],
 ['⏳','«پروژه‌ها»: بخش‌های تکراری موعد یکی شد و تنظیمات موعد هم داخل همان بخش «موعدها» آمد (دیگر در تنظیمات جدا نیست).','Projects: the duplicate deadline sections are now one, and deadline settings live inside that same Deadlines section (no longer separate in Settings).'],
 ['🛡','هشدار «پشتیبان کامل نگرفته‌ای» دیگر بی‌جا نمی‌آید: هر نوع پشتیبان (فایل ساده، کامل، همگام‌سازی) حساب می‌شود. «تازه‌ها» هم کوتاه شد و می‌شود نمایش خودکارش را خاموش کرد.','The “no backup” warning no longer shows by mistake: any backup type (plain file, full, sync) counts. “What’s new” is shorter and its auto-popup can be turned off.'],
 ['🏮','صفحه‌ی انتظار هوشمند: همیشه مسیر کامل فانوس را نشان می‌دهد (حداقل ~۲ ثانیه)، تا تازه‌ترین نسخه آماده نشده وارد برنامه نمی‌شود و نسخه‌ی قدیمی دیده نمی‌شود.','Smarter loading screen: always plays the full lantern path (~2 s minimum), and waits for the newest version so you never see an old one first.'],
 ['🏮','آیکون اعلان‌ها تازه شد: فانوسی با حرف D داخلش (با APK تازه دیده می‌شود).','New notification icon: a lantern with a D inside (visible with a new APK).'],
 ['⚡','باز شدن برنامه سریع‌تر شد: با اینترنت کند یا فیلتر دیگر صفحه‌ی سفید چند ثانیه‌ای نمی‌ماند (بخشی از این اصلاح با APK تازه فعال می‌شود).','Faster app start: on a slow or filtered connection the white screen no longer lingers for seconds (part of this fix needs a new APK).'],
 ['🧍','مرد در آیکون اعلان‌ها بزرگ‌تر و خواناتر شد (با APK تازه دیده می‌شود).','The figure in the notification icon is bigger and clearer (visible with a new APK).'],
 ['🏮','صفحه‌ی انتظار تازه: فانوس‌هایی که آرام بالا می‌روند، ماه و ستاره، و نوار پیشرفت.','New loading screen: lanterns drifting up under the moon and stars, with a progress bar.'],
 ['🌕','آیکون اعلان‌ها عوض شد: مرد روی قله زیر ماه کامل (آیکون رنگی بزرگ + نسخه‌ی تک‌رنگ نوار وضعیت). برای دیدن آن APK تازه لازم است.','New notification icons: a lone figure on a peak under a full moon (colour large icon + mono status-bar icon). Needs a new APK to appear.'],
 ['🔁','پیام «نسخه‌ی تازه آماده است» حالا فقط وقتی می‌آید که واقعاً نسخه‌ی تازه‌تری از آنچه اجراست روی سایت باشد؛ شماره‌ی نسخه هم در پیام نوشته می‌شود و تکرار بی‌دلیل ندارد.','The “new version ready” notice now appears only when the site really has a newer version than the one running; the version numbers are shown and it no longer repeats.'],
 ['⏳','موعدها (افزودن، فهرست، هشدارها، دسته‌ها) حالا فقط در «پروژه‌ها» هستند؛ تقویمِ برنامه فقط نقطه‌های رنگی و یک دکمه‌ی رفتن دارد. هیچ قابلیتی حذف نشد.','Deadlines (add, list, alerts, categories) now live only in “Projects”; the plan calendar keeps the coloured dots and a shortcut. Nothing removed.'],
 ['🧩','تب «افزونه‌ها و گزارش» رفت داخل «داده‌ها»: افزودن تغییر، پشتیبان کامل، نصب‌شده‌ها و گزارش داده‌ها یک‌جا؛ تحلیل گزارش در نتیجه یک کارت با ۵ بخش شد. هیچ قابلیتی حذف نشد.','The “Extensions & report” tab moved into Data (add change, full backup, installed, data report); report analysis is one card with 5 sections. Nothing removed.'],
 ['🧭','تنظیمات ظاهر مرتب‌تر شد: «منو و بخش‌ها» و «نمایش خانه» دو کارت یکپارچه‌اند و «جمله‌ی تم» کنار بقیه‌ی تنظیم‌های جمله‌ها آمد؛ هیچ تنظیمی حذف نشد.','Look settings tidied: “Menu & sections” and “Home display” are now two cards, and the theme quote toggle sits with the other quote settings; nothing removed.'],
 ['🎨','«استودیو و بسته‌های تم» یک کارت شد: واردکردن و خروجی تم، استودیو و بسته‌های تم (بخش پیشرفته)؛ هیچ قابلیتی حذف نشد.','Theme studio & packs is now one card: import/export, studio and packs (advanced); nothing removed.'],
 ['🔔','«مرکز اعلان» کامل شد: همه‌ی تنظیم‌های اعلان در یک کارت با ۵ بخش (اجازه و سلامت، صدا، زمان‌ها، اعلان‌های تکمیلی، گروه‌بندی)؛ دکمه‌ی تکراریِ «درخواست اجازه» برداشته شد؛ هیچ تنظیمی حذف نشد.','Notification centre completed: every notification setting in one card with 5 sections; the duplicate “allow notifications” button is gone; no setting removed.'],
 ['🧹','مرتب‌سازی: همگام‌سازی خودکار (Drive یا هر پوشه) حالا داخل «مرکز پشتیبان» است با توضیح کوتاه؛ «ویجت و اعلان زنده» کارت جدا شد؛ کارت تکراریِ «نمایش جمله‌ها در صفحه‌ی اصلی» یک‌بار نشان داده می‌شود. هیچ قابلیتی حذف نشد','Tidy-up: auto sync (Drive or any folder) now lives inside the Backup centre with a short explanation; “Widget & live notification” is its own card; the duplicate “Quotes on the home screen” card shows once. No feature removed'],
 ['📶','برنامه‌ی اندروید حالا فایل‌ها را داخل خودش دارد: با وای‌فای فیلترشده یا بدون اینترنت هم باز می‌شود (صفحه‌ی سفید نمی‌ماند)؛ هر وقت اینترنتِ رسیده به GitHub باشد خودش نسخه‌ی تازه را می‌گیرد و خبر می‌دهد؛ نصب دوباره فقط برای تغییر بخش بومی لازم است (APK نو، حالت bundled)','The Android app now carries its files: it opens on filtered Wi-Fi or offline (no white screen); whenever GitHub is reachable it fetches the new version itself and tells you; reinstall is only needed for native changes (new APK, bundled mode)'],
 ['📌','پنل سریع اعلان نو شد: دکمه‌های آیکون‌دار، شروع شمارش با یک لمس روی فعالیت، شمارنده‌ی بزرگ با مکث/پایان/لغو، 📝 یادداشت؛ ⚡+۱۵ حذف شد و متن ماندگار هم نیست. فعالیت‌ها: خودکار / دستی / ترکیبی (تنظیمات ← همگام‌سازی و ویجت ← 📌؛ APK نو)','New quick panel: icon buttons, one tap on an activity starts counting, big timer with pause/stop/cancel, 📝 note; ⚡+15 removed and no lingering text. Activities: auto / manual / mixed (Settings → Sync & widget → 📌; new APK)'],
 ['🌱','«هفته‌ی اول ساده» (اختیاری، در آخر راهنمای شروع): فقط پایه‌ی پلنر را نگه می‌دارد و عادت‌ها، یادآوری‌ها، جملات و آکادمی را ۷ روز پنهان می‌کند؛ بعدش یک نوار می‌گوید باز کنی؛ هیچ داده‌ای پاک نمی‌شود','“Simple first week” (optional, at the end of the start guide): keeps only the planner basics and hides habits, reminders, quotes and Academy for 7 days; then a bar offers to bring them back; nothing is deleted'],
 ['🛡','اعلان یادآوری پشتیبان حالا طبق بازه‌ی خودت (تنظیمات ← مرکز پشتیبان) می‌آید، می‌گوید چند روز گذشته و با لمس مستقیم به «مرکز پشتیبان» می‌رود؛ از آن‌جا پشتیبان را در Drive یا تلگرام نگه دار','The backup reminder now follows your own interval (Settings → Backup centre), says how many days it has been, and opens the Backup centre on tap, where you can keep the file in Drive or Telegram'],
 ['🔑','APK همیشه با یک امضای ثابت ساخته می‌شود: از این به بعد نسخه‌ی تازه روی قبلی نصب می‌شود و اطلاعات نمی‌پرد (اولین بار بعد از این تغییر: پشتیبان بگیر و اپ قبلی را پاک کن)','APKs are now always signed with one fixed key: new versions install over old ones without losing data (first time after this change: back up and uninstall the old app)'],
 ['🧩','ویجت: دو خط تازه — ⏭ برنامه‌ی بعدیِ امروز و 🔥 رگه‌ی روزها (تنظیمات ← همگام‌سازی و ویجت؛ هرکدام قابل خاموش‌شدن؛ APK نو)','Widget: two new lines — ⏭ next plan today and 🔥 day streak (Settings → Sync & widget; each can be switched off; new APK)'],
 ['⏳','هشدار موعد هوشمندتر: هرچه عقب‌تر یا نزدیک‌تر، لحن جدی‌تر؛ مقدار کار لازم برای امروز در متن می‌آید؛ اگر امروز به اندازه‌ی کافی کار کرده‌ای ساکت می‌ماند؛ در حالت خیلی جدی یک یادآوری ۴ ساعت زودتر هم می‌آید (موعدها ← ⚙)','Smarter deadline alert: tone gets firmer the further behind / closer you are; today’s needed work is in the text; silent if you already worked enough today; in the serious level an extra reminder 4h earlier (Deadlines → ⚙)'],
 ['📌','پنل سریع پین‌شده در اعلان‌ها: ⏱ شروع (پنجره‌ی شناور انتخاب فعالیت + شمارش با مکث/پایان)، ⚡ +۱۵ و 📝 یادداشت سریع بدون باز کردن برنامه (APK نو). ماه سفیدتر و صفحه‌ی آماده‌سازی زیباتر','Pinned quick panel in notifications: ⏱ Start (floating activity picker, count with pause/stop), ⚡ +15 and 📝 quick note without opening the app (new APK). Whiter moon and a prettier start screen'],
 ['📚','تب «دوره‌ها»ی آکادمی برگشت (با شروع تمیز پنهان شده بود؛ داده‌ها هیچ‌وقت پاک نشده بودند)','The Academy “Courses” tab is back (the clean-start change had hidden it; your data was never deleted)'],
 ['🌐','زبان و تقویم در یک کارت (تنظیمات ← ظاهر)','Language and calendar in one card (Settings → Look)'],
 ['💾','همه‌ی کارهای پشتیبان در یک کارت «مرکز پشتیبان»: پشتیبان کامل، فایل ساده، ارسال، نسخه‌های خودکار، رمز، یادآوری و حذف داده‌ها؛ تکراری‌ها نمانده‌اند','All backup jobs in one “Backup centre” card: full backup, simple file, send, snapshots, password, reminder, delete data; duplicates gone'],
 ['▣','موعد مرحله‌دار (مثلاً پیش‌نویس ← بازبینی ← تحویل) با پیشرفت روی کارت؛ نقطه‌ی موعد در تقویم به رنگ فوریت','Deadlines with steps (draft → review → submit) and progress on the card; calendar deadline dots now show urgency colour'],
 ['🌕','ماه کامل و زیبا: روی صفحه‌ی آماده‌سازی و در اعلان‌ها (آرم رنگی کنار اعلان + نماد ماه در نوار بالا)؛ دکمه‌ی موعد روشن‌تر: «موعدها و تنظیمات»','A full, beautiful moon on the start screen and in notifications; clearer deadline button: “Deadlines & settings”'],
 ['🧩','ویجت تازه: شمارنده‌ی موعد نزدیک (با رنگ هشدار) و نوار سهمیه‌ی امروز؛ هرکدام قابل خاموش‌شدن (APK نو)','New widget: nearest-deadline counter (level colour) and today-quota bar, each switchable (new APK)'],
 ['🌙','شروع بدون پرش: صفحه‌ی آماده‌سازی تا آماده‌شدن کامل برنامه؛ لمس اعلان با برنامه‌ی بسته (APK نو) و کارت موعد فقط یک دکمه','Jump-free start: a short splash until the app is fully ready; notification tap from a closed app (new APK); deadline card has a single button'],
 ['⚙','تنظیمات موعد یک‌جا شد (موعدها ← ⚙): طرح، رنگ و سطح، جمله‌ها، یادآوری پیش‌فرض (تا ۱ هفته قبل)، طرح جدا برای هر موعد و هشدار هوشمند','Deadline settings in one place (Deadlines → ⚙): look, colours & levels, sentences, default reminders (up to 1 week), per-deadline look and a smart alert'],
['⚡','شروع تمیز: دیگر اول صفحه‌ی قدیمی دیده نمی‌شود؛ اعلانِ برنامه‌ی بسته هم دقیق به آیتم می‌رود','Clean start: no more old-home flash; tapping a notification with the app closed now lands on the exact item'],
 ['🎯','لمس اعلان حالا دقیقاً همان آیتم را باز می‌کند و برجسته می‌کند (یادآوری، عادت، موعد، تایمر، برنامه‌ی فردا، گزارش)؛ یک نوار کوچک می‌ماند تا هر وقت خواستی ببندی یا جای دیگر بروی.','Tapping a notification now opens and highlights the exact item (reminder, habit, deadline, timer, tomorrow’s plan, report); a small bar stays so you can close it or go elsewhere.'],
 ['📈','جبران و تأخیر پروژه: «باید تا امروز اینجا می‌بودی»، سهمیه‌ی تطبیقی امروز، تاریخ پایان طبق برنامه در برابر ریتم واقعی، اثر هر روزِ ۷ روز اخیر و هزینه‌ی وقت تلف‌شده.','Project catch-up & delay: where you should be today, adaptive share for today, plan vs real finish date, effect of each of the last 7 days and the cost of wasted time.'],
 ['❓','دکمه‌های اعلان چک‌این حالا می‌پرسند دقیقاً چه کاری بود (چند فعالیت پیشنهادی + «فعالیت دیگر»)؛ اگر خواستی می‌توانی «حدس بزن» را روشن کنی.','Check-in notification buttons now ask exactly what you did (a few suggested activities + “other”); you can switch on “guess” mode if you prefer.'],
 ['⚡','ثبت سریع از اعلان دقیق‌تر شد: متن اعلان می‌گوید هر دکمه چه فعالیتی ثبت می‌کند، ثبت‌ها «تأییدنشده» می‌مانند و روی خانه می‌توانی تأیید یا اصلاحشان کنی.','Quick log from notifications is clearer: the notification says which activity each button logs, logs stay “unconfirmed” until you confirm or fix them on Home.'],
 ['🔔','اعلان چک‌این ساعتی حالا سه دکمه دارد: «مفید / استراحت / تلف شد» (یک لمس، همان ساعت ثبت می‌شود). صدای جدا هم برای چک‌این و یادآور باقی‌مانده انتخاب می‌شود.','The hourly check-in notification now has three buttons: Useful / Rest / Wasted (one tap logs that hour). Check-in and remaining-goal reminders also get their own sound.'],
 ['🧱','آیکون توپُر: یک طرح کامل تازه برای همه‌ی آیکون‌های منو و تنظیمات (استودیوی آیکون ← طرح ← توپُر)، روی همه‌ی تم‌ها.','Solid icons: a complete new filled icon set for every menu and settings icon (Icon studio → Set → Solid), on all themes.'],
 ['🎨','ظاهر آیکون‌های منو: در استودیوی آیکون، طرح (مطابق تم / یکسان / ایموجی)، قاب (دایره، گرد، شش‌ضلعی، کاشی)، رنگ (رنگارنگ) و پرکردگی نرم را برای همه‌ی تم‌ها انتخاب کن.','Menu icon look: in Icon studio pick the set (theme / uniform / emoji), frame (circle, rounded, hexagon, tile), colour (colourful) and soft fill for every theme.'],
 ['📓','دفترچه‌ی خطای آکادمی: همه‌ی اشتباهات یک‌جا، یا به‌تفکیک درس یا مبحث (با نشان دادن منبع)، و «خودآزمایی» بدون نام مبحث برای سنجش اینکه سؤال را تشخیص می‌دهی.','Academy error notebook: all mistakes in one place, or by lesson / topic (with the source shown), plus a topic-free self-test to check whether you recognise the question.'],
 ['📥','تقویم گوشی: رویدادهای فایل تقویم (.ics) را به «ساعت پر» وارد کن (با پیش‌نمایش)؛ ساعت‌های پر هم در خروجی تقویم می‌آیند.','Phone calendar: import events from a calendar file (.ics) into Busy blocks (with preview); busy blocks are also included in the calendar export.'],
 ['🧩','تعویض آیکون‌ها: در تنظیمات ← ظاهر ← استودیوی آیکون، هر یک از ۱۶ آیکون اصلی را با ایموجی دلخواه عوض کن (بازنشانی هم هست).','Swap icons: in Settings → Look → Icon studio, replace any of the 16 main icons with your own emoji (reset available).'],
 ['🧭','راهنمای شروع اگر نیمه‌کاره بماند: در پنل «؟» می‌نویسد «ادامه‌ی راهنما (مرحله‌ی X از ۸)» و بالای خانه یک نوار نازکِ بسته‌شدنی دارد','If the start guide is left unfinished: the “?” panel says “Continue the start guide (step X of 8)” and Home shows a thin dismissible bar'],
 ['🕒','تایم‌لاین خانه: با فلش‌ها هر روز گذشته را ببین، روی هر بازه بزن تا ویرایش/حذف شود، روی بخش خط‌خطی بزن یا «＋ ثبت» تا فعالیت آن روز را ثبت کنی','Home timeline: step through past days with the arrows, tap a block to edit/delete, tap a hatched part or “＋ Log” to log an activity on that day'],
 ['⏱','وقت مفید و اتلاف: نوار کوچک در خانه (زیر «نتیجه») و برنامه، کارت کامل در نتیجه و گزارش — مفید برای هدف، ضروری زندگی، اتلاف/تفریح و ثبت‌نشده، با «اگر بهتر شوی». نقش هر فعالیت در ویرایش فعالیت قابل‌تغییر است','Useful vs wasted time: slim bar on Home and Plan, full card in Results and Report — useful, life needs, wasted/leisure and unlogged, with a “what if” line. Change an activity’s role in its edit form'],
 ['⏳','کارت موعد خانه بازطراحی شد: سطح هشدار (آرام ← نزدیک ← هشدار ← بحرانی)، ۷ طرح، جهت پُر/خالی برای هر طرح، جمله‌ی قابل‌ویرایش برای هر سطح؛ باگ دوبار آمدن رفع شد (تنظیمات ← زبان و ظاهر ← کارت موعد خانه). تنظیمات جمله‌ها هم به همان‌جا رفت','Home deadline card redesigned: warning levels, 7 styles, per-style fill/drain direction, editable sentence per level; duplicate-card bug fixed (Settings ← Language & look). Sentence settings moved there too'],
 ['🎯','«نمای آرام» اختیاری: انیمیشن‌ها، دکمه‌های شناور و بخش‌های تزئینی/فرعی خانه را پنهان می‌کند؛ هیچ‌چیز حذف یا عوض نمی‌شود و با «نمایش همه» برمی‌گردد (تنظیمات ← زبان و ظاهر، یا جست‌وجوی ⚡)','Optional “Calm view”: hides animations, floating buttons and decorative/secondary Home sections; nothing is removed or changed and “Show all” brings it back (Settings ← Language & look, or ⚡ search)'],
 ['🕒','اعلان اختیاری «الان چه می‌کنی؟» (هر ۳۰/۶۰/۹۰/۱۲۰ دقیقه): با لمس اعلان، آخرین بازه‌ی ثبت‌نشده را یک‌لمسی ثبت می‌کنی (تنظیمات ← اعلان‌ها و زمان؛ پیش‌فرض خاموش)','Optional “What are you doing?” check-in every 30/60/90/120 min: tap the notification to log the last unlogged span in one tap (Settings ← Notifications; off by default)'],
 ['🧹','نتیجه ← آمار مرتب‌تر شد: ۱۳ بخش در ۴ گروه (مقایسه، زمان و فعالیت‌ها، روند و بهترین روزها، انرژی و یادگیری)؛ کارت‌های قدیمی داشبورد در تنظیمات ← زبان و ظاهر جمع شد؛ هیچ‌چیز حذف نشده','Results ← Stats tidied: 13 sections in 4 groups (Compare, Time & activities, Trends & best days, Energy & learning); old dashboard cards folded in Settings; nothing removed'],
 ['🔐','پشتیبان کامل می‌تواند با رمز قفل شود؛ بازیابی خودش رمز را می‌خواهد (تنظیمات ← داده‌ها ← مرکز پشتیبان)','The full backup can be locked with a password; restore asks for it (Settings ← Data ← Backup centre)'],
 ['⏳','یادآوری انتظار باقی‌مانده: در سه ساعت دلخواه می‌گوید امروز چقدر انجام شده و چقدر مانده (تنظیمات ← اعلان‌ها و زمان)','Remaining-goal reminders: at three chosen times it tells you what is done and what is left today (Settings ← Notifications)'],
 ['⭐','بعد از هر ثبت یک پنل کوچک و اختیاری برای امتیاز (انرژی، حس، موفقیت، دقت) می‌آید؛ میانگین‌ها در نتیجه ← آمار و روشن/خاموش‌کردنش در تنظیمات ← اعلان‌ها','After each log a small optional panel lets you rate energy, feeling, success and accuracy; averages in Results ← Stats; toggle in Settings ← Notifications'],
 ['⏳','کارت «موعد بعدی» در خانه چند طرح تازه دارد (کارت اصلی، سه موعد، خط زمان، خط باریک) — با 🎨 عوض کن؛ عادت می‌تواند با فعالیت پیوند شود و خودکار تیک بخورد؛ یادآور سالانه؛ افزودن سریع موعد/یادآور از تقویم','Home deadline card has new styles (hero, next three, timeline, slim) — switch with 🎨; habits can link to an activity and tick automatically; yearly reminders; quick-add deadline/reminder from the calendar'],
 ['⚙','تنظیمات مرتب‌تر شد: «مرکز اعلان» (اجازه و سلامت، صدا، زمان‌ها و تکرار، گروه‌بندی و تاریخچه) یک‌جاست؛ زبان و تقویم و ظاهر کنار هم‌اند.','Settings tidied: one Notification centre (permission & health, sound, times & repeats, grouping & history); language, calendar and look sit together.'],
 ['📊','«نتیجه» حالا ۳ زبانه دارد: نتیجه‌ی امروز، آمار و روند (با گزارش ماهانه، پیش‌بینی و ساعت‌های طلایی)، گزارش و خروجی (با کارت اشتراک). بخش‌های بلند جمع‌شونده‌اند.','Results now has 3 tabs: Today, Stats & trends (with monthly report, forecast and golden hours), Reports & export (with the share card). Long sections are collapsible.'],
 ['🏁','پیش‌بینی پایان پروژه: بگو روزی چند ساعت و هفته‌ای چند روز؛ می‌بینی روزانه/هفتگی/ماهانه/تا موعد چقدر می‌شود و کدام روز به هدف می‌رسی (و چند روز زودتر یا دیرتر از موعد). برای هر بخش هم جدا. در راهنما، خانه، برنامه، تقویم و موعدها هم می‌آید.','Project finish forecast: set hours a day and days a week; see daily/weekly/monthly/until-deadline totals and the date you reach the goal (days early or late). Per part too. Also in the guide, Home, Plan, Calendar and Deadlines.'],
 ['📈','در «پروژه‌ها» هر پروژه حالا پیش‌بینی دارد: با هفته‌ای X ساعت، روزی/ماهی/تا موعد چقدر می‌شود و بودجه تأمین است یا نه.','Each project now shows a forecast: at X h/week, how much per day/month/until the deadline and whether the budget is covered.'],
 ['📅','تقویم یکپارچه شد: روی ماه نقطه‌های رنگی تعطیلی، مناسبت، موعد، یادآوری، ساعت پر و برنامه را می‌بینی؛ با لمس هر روز جزئیاتش و دکمه‌ی «برنامه‌ریزی این روز» می‌آید.','Unified calendar: coloured dots for holidays, occasions, deadlines, reminders, busy blocks and plans; tap a day for details and “Plan this day”.'],
 ['🗓','«برنامه» ساده‌تر شد: ۴ زبانه (روز، توقع، ساعت‌پر/عادت/یادآور، تقویم و موعد). نوار ۷ روزه، کارهای عقب‌افتاده، یک کارت برای نوشتن و فهرست و جمع، تکرار کنار هر کار. «فعالیت‌ها» یک مدیر کامل با برچسب جدید و تغییر نام شد.','Plan simplified: 4 tabs (Day, Goals, Busy/Habits/Reminders, Calendar & deadlines). 7-day strip, overdue bar, one card to write + list + total, repeat next to each item. Activities is now a full manager with new tags and rename.'],
 ['🛡','یادآوری پشتیبان حالا می‌گوید: تنظیمات ← داده‌ها ← مرکز پشتیبان.','The backup reminder now points to Settings → Data → Backup centre.'],
 ['🧮','راهنمای جدید حالا اول کار می‌آید (راهنمای قدیمی نمی‌آید). در قدم «توقع‌ها» ساعت هفتگی را بنویس تا حساب هر روز، هفته، ماه و مجموع تا موعد را ببینی.','The new guide now opens first (the old one is gone). In the Expectations step, type weekly hours to see per-day, week, month and total-until-deadline maths.'],
 ['🧭','راهنمای شروع از نو ساخته شد: صفحه‌ی کامل و قدم‌به‌قدم (زبان، تقویم، پروژه، برنامه، توقع، ثبت، نتیجه). پروژه و بخش‌ها و برنامه‌ی هفتگی را همان‌جا می‌سازی. دکمه‌ی «؟» هم نکته‌ی همان صفحه را نشان می‌دهد.','Start guide rebuilt: a full-screen step-by-step wizard (language, calendar, project, schedule, expectations, log, results). Build projects, parts and your weekly schedule right there. The “?” button now shows a tip for the current page.'],
 ['🧭','راهنمای شروع با ترتیب جدید: زبان ← تقویم ← پروژه‌ها ← برنامه‌ی من ← توقع‌ها ← ثبت ← نتیجه ← تنظیمات. ⚡ دسترسی سریع در خانه؛ «شخصی‌سازی» خانه (ترتیب، حذف، افزودن کارت)؛ ⭐ فعالیت‌های ضروری و ＋ فعالیت جدید در همه‌ی انتخاب‌ها؛ باگ پنجره‌ی یادداشت درست شد.','New guide order: language → calendar → projects → my schedule → expectations → track → results → settings. ⚡ Quick access on Home; Customize Home (reorder, hide, add cards); ⭐ essential activities and ＋ new activity everywhere; quick-note bug fixed.'],
 ['📝','خانه ساده‌تر شد: «تمرکز اصلی» و «پیشرفت اهداف روزانه» داخل «برنامه‌ی امروز»، «مقایسه» در «نتیجه ← آمار»، یادداشت سریع با دکمه‌ی 📝، و ✏️ کنار فعالیت‌ها برای ویرایش فعالیت و برچسب.','Simpler Home: Main focus & daily goals inside Today’s plan, Compare in Results → Stats, quick note via 📝, and ✏️ next to activities to edit them and their tags.'],
 ['🧹','خانه‌ی همه‌ی تم‌ها ویژگی‌های خودش را دارد و فقط یک «ثبت فعالیت» دارد؛ زبانه‌های تکراری میزکار (امروز، برنامه، فردا، تقویم، اهداف) برداشته شد و کارشان در خانه/برنامه/پروژه‌هاست.','Every theme keeps its own home features with a single Activity Log; duplicate Workspace tabs (today, plan, tomorrow, calendar, goals) removed — they live in Home/Plan/Projects.'],
 ['🏠','منو: «خانه» (همان صفحه‌ی خانه‌ی تم‌ها با کارت‌های ادغام‌شده)؛ صفحه‌ی «ابزارهای من» برداشته شد و میان‌بُرها (جست‌وجو، یادداشت، فعالیت‌ها، جملات) بالای خانه‌اند.','Menu: “Home” (the theme home with merged cards); “My tools” page removed — shortcuts (search, notes, activities, quotes) sit on top of Home.'],
 ['🎨','«امروز» حالا هیرو، گالری، جمله و میان‌بُرهای خودِ هر تم را دارد؛ مرکز پشتیبان یک‌جا شد؛ «بعدی‌چی؟»، «موعد بعدی» و «شخصی‌سازی خانه» که تکراری بودند از امروز برداشته شد (موعد بعدی یک خط در برنامه‌ی امروز است).','Today now shows each theme’s own hero, gallery, quote and shortcuts; one Backup centre; duplicate “What next”, “Next deadline” and “Customize home” removed from Today.'],
 ['🗓','منوی تازه: امروز · برنامه · پروژه‌ها · نتیجه · آکادمی · تنظیمات. صفحه‌ی «برنامه» همه‌چیز برنامه‌ریزی را دارد: روز دلخواه، انتظار هفته/ماه، ساعت‌های پر (کلاس/کار)، عادت، یادآور، موعد.','New menu: Today · Plan · Projects · Results · Academy · Settings. The Plan page holds day plan, weekly/monthly expectations, busy blocks, habits, reminders, deadlines.'],
 ['🖥','حالت تمرکز (صفحه‌ی تاریک با شمارش‌معکوس و استراحت) در کارت «ثبت» ← پومودورو دوباره پیداست؛ استودیوی تم و بسته‌های تم برگشتند؛ ۹ زبانه‌ی «امروز» (بعدی، ثبت، شروع…) یک کارت شد','Focus mode (dark screen with countdown and breaks) is back in Track → Pomodoro; Theme Studio and theme packs are restored; the 9-tab Today card is now one card'],
 ['🎓','پروژه + موعد + هدف + عادت + یادآور در یک جا: پروژه می‌تواند موعد داشته باشد یا نه، عادت‌ها و یادآورهایش همان‌جاست، و موعدها و هدف‌های قبلی با یک دکمه پروژه می‌شوند','Project + deadline + goal + habits + reminders in one place: a project may or may not have a deadline, its habits and reminders live there, and your earlier deadlines/goals become projects in one tap'],
 ['🧹','چند کارت بی‌استفاده برداشته شد (بنر خانه‌ی جدید، راستی‌آزمایی v4، بسته‌های تم و استودیوی تم، پیشنهاد فردا در تب برنامه، چیدمان داشبورد)؛ پیشنهاد فردا در تب «برنامه‌ی فردا» هست','Unused cards removed (New-home banner, v4 verification, theme packs & Theme Studio, tomorrow suggestion in Plan tab, dashboard layout); suggestions live in the “Tomorrow’s plan” tab'],
 ['⏱','یک کارت «ثبت» به‌جای چند کارت جدا (کرنومتر، شمارش‌معکوس، پومودورو، ثبت سریع، ثبت دستی، میانبرها)؛ شیوه‌ی هر فعالیت یادش می‌ماند. کارت‌های هم‌هدف در تنظیمات و برنامه زیر یک عنوان تاشو جمع شدند','One “Track” card instead of several (stopwatch, countdown, Pomodoro, quick and manual log, shortcuts); each activity remembers its mode. Related cards in Settings and Plan are grouped under one collapsible title'],
 ['🎴','نوار تم (سلام، تاریخ، ساعت و جمله‌ی شخصیت) بالای همه‌ی صفحه‌ها و قابل‌بستن؛ «برنامه‌ی فردا» حالا تبی در میزکار است؛ تاریخ‌ها همه‌جا طبق تقویم انتخابی (شمسی/میلادی)','A theme bar (greeting, date, time, character quote) on every page, closable; “Tomorrow’s plan” is now a Workspace tab; every date follows your chosen calendar'],
 ['🎓','پروژه‌ها: پروژه ← بخش ← نوع کار با موعد و بودجه‌ی ساعت؛ آهنگ لازم برای امروز، هفته و ماه، و افزودن به برنامه‌ی فردا با یک ضربه','Projects: project → part → work type with a deadline and hour budget; the pace you need today, this week and this month, and one-tap add to tomorrow’s plan'],
 ['🌙','برنامه‌ی فردا در یک صفحه‌ی مرتب (هر خط یک کار)، صفحه‌ی «امروز» با ثبت یکپارچه و تایم‌لاین، و «نتیجه‌ی امروز» — منوی ساده (قابل‌برگشت به کلاسیک از «بیشتر»)','Tomorrow’s plan on one tidy page (one item per line), a Today page with unified tracking and a timeline, and Today’s result — simple menu (switch back to classic under “More”)'],
 ['✍️','افزودن سریع با جمله («فردا ۱۸ ریاضی ۲ ساعت»)، ساعت‌های طلایی و مناسبت‌های ایران (تب «برنامه» و نتیجه‌گیری)','Quick add with a sentence (“tomorrow 18:00 maths 2 hours”), golden hours and Iranian occasions (Plan tab and Results)'],
 ['🔒','قفل برنامه با PIN و رمزگذاری فایل همگام‌سازی (تنظیمات ← داده‌ها)','App lock with a PIN and an encrypted sync file (Settings → Data)'],
 ['🖼','کارت اشتراک پیشرفت (نتیجه‌گیری ← کارت اشتراک) و ورود CSV (تنظیمات ← داده‌ها)','Progress share card (Results → Share card) and CSV import (Settings → Data)'],
 ['🔔','تیک عادت از خود اعلان، اعلان‌های گروهی و تاریخچه‌ی اعلان‌ها (تنظیمات ← زمان)','Tick a habit from the notification, grouped notifications and a notification history (Settings → Time)'],
 ['🧩','ویجت در سه اندازه با تیک عادت و «+۱۵ دقیقه» بدون باز کردن برنامه (نیازمند APK جدید)','Widget in 3 sizes with habit ticks and “+15 min” without opening the app (needs the new APK)'],
 ['🧩','کارت «امروز» با تب: بعدی، ثبت، شروع، کار، چرخه، تمرکز، الگو، مرور، فردا','The “Today” card with tabs: next, log, start, task, rhythm, focus, pattern, review, tomorrow'],
 ['🗑','سطل بازیافت: هر چیز حذف‌شده تا ۴۵ روز برمی‌گردد (تنظیمات ← داده‌ها)','Recycle bin: anything deleted comes back for 45 days (Settings → Data)'],
 ['📅','برنامه‌ی فردا (پیشنهاد)، قالب روز/هفته و حالت امتحان','Tomorrow’s plan (suggested), day/week templates and exam mode'],
 ['⏳','برآورد ساعت موعد و پیش‌بینی «به موقع می‌رسی؟»','Deadline hour estimates and an on-time forecast'],
 ['🌙','ساعت سکوت، مزاحم نشو، خلاصه‌ی پایان هفته و هشدار تایمر فراموش‌شده','Quiet hours, Do not disturb, weekly summary and forgotten-timer alert'],
 ['🔄','همگام‌سازی بین دستگاه‌ها با یک فایل (ویرایش و حذف هم)','Sync between devices through one file (edits and deletions too)'],
 ['✦','دکمه‌ی راهنما: قابل‌کشیدن، با اندازه و فاصله‌ی دلخواه + بررسی سلامت','Help button: draggable, adjustable size and edge distance + health check'],
 ['🔎','جست‌وجوی ثبت‌ها و یادداشت‌ها، زیرمرحله‌ی اهداف و بخشش عادت‌ها','Search entries & notes, goal steps and habit forgiveness'],
 ['⏱','تایمر زنده در اعلان، ویجت خانه و دکمه‌های اعلان (با APK جدید)','Live timer notification, home widget and notification buttons (new APK)']];
const seen=()=>{try{return localStorage.getItem('dani_seen_ver')||''}catch(e){return''}};
const mark=()=>{try{localStorage.setItem('dani_seen_ver',VER)}catch(e){}};
function wnHTML(){const R=x=>'<div class="cwr" style="display:flex;gap:8px"><span aria-hidden="true">'+x[0]+'</span><span dir="auto">'+T(x[1],x[2])+'</span></div>',top=WN.slice(0,4),rest=WN.slice(4);return'<div style="max-width:440px">'+daniH('🆕','چه چیزی تازه است','What\'s new')+top.map(R).join('')+(rest.length?'<details style="margin-top:8px"><summary style="cursor:pointer;opacity:.75">'+T('تغییرات قبلی ('+fa(String(rest.length))+')','Earlier changes ('+rest.length+')')+'</summary>'+rest.map(R).join('')+'</details>':'')+'<div class="row" style="margin-top:10px"><button class="p" data-a="ob_close">'+T('باشه','Got it')+'</button></div></div>'}
H.fx_new=()=>{mark();modal(wnHTML())};
window.daniVer=VER;
H.fx_upd=async()=>{toast(T('در حال به‌روزرسانی…','Updating…'));try{const rs=navigator.serviceWorker&&await navigator.serviceWorker.getRegistrations();if(rs)for(const r of rs)await r.unregister()}catch(e){}
  try{for(const k of await caches.keys())await caches.delete(k)}catch(e){}try{sessionStorage.removeItem('dani_gate');localStorage.removeItem('dani_ota_told')}catch(e){}
  setTimeout(()=>{location.href=location.pathname+'?fresh='+Date.now()},500)};
setTimeout(()=>{try{if(seen()===VER)return;const used=(db.entries&&db.entries.length>3)||(db.set.ob&&(db.set.ob.fin||db.set.ob.dis));
  if(!used||FX().wnOff){mark();return}
  if(document.querySelector('#ovl .ov'))return;mark();modal(wnHTML())}catch(e){}},5500);
/* ---------- نمونه‌داده ---------- */
H.fx_smp=()=>{if(db.entries.some(e=>e.smp))return toast(T('نمونه‌داده از قبل هست','Sample data already loaded'),1);
  const A=[['مطالعه‌ی نمونه','Sample study','learn','#3b82f6'],['ورزش نمونه','Sample workout','personal','#10b981'],['پروژه‌ی نمونه','Sample project','work','#8b5cf6']].map(x=>({id:'smp'+uid(),name:T(x[0],x[1]),cat:x[2],tags:[],color:x[3],prio:'',goalDay:0,goalWeek:0,subs:[],desc:'',active:true,days:[],smp:1}));
  A.forEach(a=>db.acts.push(a));const t=todayISO();
  for(let i=0;i<7;i++){const d=addD(t,-i);A.forEach((a,j)=>{if((i+j)%3===2)return;const min=[50,30,75,40][(i+j)%4],h=9+j*3;
    db.entries.push({id:'smp'+uid(),date:d,actId:a.id,min,start:String(h).padStart(2,'0')+':00',end:hm(tm(String(h).padStart(2,'0')+':00')+min),note:'',src:'manual',smp:1})})}
  save();closeM();toast(T('نمونه‌داده اضافه شد؛ از راهنما می‌توانی پاکش کنی','Sample data added; remove it from Help'));render()};
H.fx_smpx=()=>{if(!confirm(T('نمونه‌داده پاک شود؟ (داده‌های خودت دست نمی‌خورد)','Remove sample data? (your own data is untouched)')))return;
  db.entries=db.entries.filter(e=>!e.smp);db.acts=db.acts.filter(a=>!a.smp);if(db.plans)Object.keys(db.plans).forEach(d=>{db.plans[d]=(db.plans[d]||[]).filter(x=>act(x.actId))});save();closeM();render()};
window.daniFx={hasSample:()=>db.entries.some(e=>e.smp),few:()=>db.entries.length<10};
/* ---------- کارت تنظیمات ---------- */
H.fx_hap=()=>{FX().hap=FX().hap?0:1;save();render()};
H.fx_an=()=>{FX().anim=FX().anim?0:1;save();render()};
H.fx_wn=()=>{FX().wnOff=FX().wnOff?0:1;save();render()};
function card(){const f=FX();
  return'<div class="c" id="fxcard">'+daniH('✨','حس برنامه','App feel')+'<div class="row"><button class="chip '+(f.hap?'on':'')+'" data-a="fx_hap">📳 '+T('لرزش ریز روی اقدام‌های مهم','Light haptics on key actions')+'</button><button class="chip '+(f.anim?'on':'')+'" data-a="fx_an">✨ '+T('انیمیشن نرم دکمه‌ها','Soft button animation')+'</button></div>'
   +'<div class="row" style="margin-top:6px"><button class="chip" data-a="fx_new">🆕 '+T('چه چیزی تازه است','What\'s new')+'</button><button class="chip '+(f.wnOff?'':'on')+'" data-a="fx_wn">🔔 '+T('نمایش خودکار تازه‌ها بعد از هر نسخه','Auto-show what\'s new after each update')+'</button></div></div>'}
{const _sp=setPage;setPage=function(){const h=_sp.apply(this,arguments);return(typeof h==='string'&&typeof stt!=='undefined'&&stt==='look')?h+card():h}}
})();
